// Native compiler of SCALE22 trace into VeriPB 3.0 cutting planes + RUP.
// Producer is untrusted: only the standard checker may certify its output.
#include <bits/stdc++.h>
using namespace std;using ll=long long;using U=uint64_t;
void req(bool b,const char*m){if(!b)throw runtime_error(m);}
U key(int a,int b){if(a>b)swap(a,b);return (U(unsigned(a))<<32)|unsigned(b);}
struct G{int r,p,m;vector<int>x;vector<char>d;ll alo=0;};
int main(int argc,char**argv){try{
req(argc==4,"usage: emit23 CNF TRACE PBP");ifstream cert(argv[2]);string magic;int n,H;req(bool(cert>>magic>>n>>H)&&magic=="SCALE22"&&n>=2&&n<=256&&H>0&&H<=4096,"cert header");vector<G>g(n);unordered_map<int,int> owner;map<int,vector<int>> machines;
for(int u=0;u<n;u++){auto&z=g[u];int k;req(bool(cert>>z.r>>z.p>>z.m>>k)&&z.r>=0&&z.r<=H&&z.p>0&&z.p<=H&&z.m>=0&&z.m<n&&k>0&&k<=4096&&z.r+z.p+k-1<=H,"group");for(int i=0;i<k;i++){int x;req(bool(cert>>x)&&x>0&&owner.emplace(x,u).second,"selector");z.x.push_back(x);}z.d.assign(k,1);machines[z.m].push_back(u);}
vector<array<int,5>> trace;set<int> needed;array<int,5>s;bool done=false;while(cert>>s[0]){req(bool(cert>>s[1]>>s[2]>>s[3]>>s[4])&&!done,"trace");auto[t,u,i,a,b]=s;req(u>=0&&u<n,"u");if(t==1)needed.insert(g[u].m);else if(t==2){req(machines.count(u),"machine");needed.insert(u);done=true;}else if(t==3)done=true;else req(t==0,"type");trace.push_back(s);}req(cert.eof()&&done,"no conclusion");
ifstream f(argv[1]);req(bool(f),"cnf open");string line;int nv=0;ll nc=0,id=0;bool header=false;vector<int>cl;unordered_map<U,ll> mutex;unordered_map<int,vector<pair<int,ll>>> impl;mutex.reserve(2000000);
while(getline(f,line)){if(line.empty()||line[0]=='c')continue;if(line[0]=='p'){istringstream ss(line);string p,cnf;req(!header&&bool(ss>>p>>cnf>>nv>>nc)&&cnf=="cnf","header");header=true;continue;}req(header,"header missing");const char*p=line.c_str();char*end;while(*p){while(isspace((unsigned char)*p))p++;if(!*p)break;long v=strtol(p,&end,10);req(end!=p&&v>=-nv&&v<=nv,"literal");p=end;if(v){cl.push_back(v);continue;}++id;if(cl.size()==2){int x=cl[0],y=cl[1];auto ax=owner.find(-x),ay=owner.find(-y);if(x<0&&y<0&&ax!=owner.end()&&ay!=owner.end()&&x!=y&&g[ax->second].m==g[ay->second].m&&needed.count(g[ax->second].m))mutex.emplace(key(-x,-y),id);if(x<0&&ax!=owner.end()&&needed.count(g[ax->second].m)&&!owner.count(abs(y)))impl[-x].emplace_back(y,id);if(y<0&&ay!=owner.end()&&needed.count(g[ay->second].m)&&!owner.count(abs(x)))impl[-y].emplace_back(x,id);}
if(!cl.empty()&&owner.count(cl[0])){auto&z=g[owner.at(cl[0])];if(!z.alo&&cl.size()==z.x.size()){auto a=cl,b=z.x;sort(a.begin(),a.end());sort(b.begin(),b.end());if(a==b)z.alo=id;}}cl.clear();}}
req(header&&id==nc&&cl.empty(),"clause count");for(auto&z:g)req(z.alo>0,"missing ALO");ofstream out(argv[3]);req(bool(out),"proof open");out<<"pseudo-Boolean proof version 3.0\nf "<<nc<<" ;\n";ll steps=0,derived=0,ac=0,energy=0,cap_reuse=0,bound_reuse=0;auto finish=[&](){out<<" ;\n";++steps;return ++id;};
auto edge=[&](int x,int y){U k=key(x,y);auto it=mutex.find(k);if(it!=mutex.end())return it->second;req(owner.at(x)==owner.at(y),"missing cross mutex");for(auto[l,i]:impl[x])for(auto[m,j]:impl[y])if(l==-m){out<<"pol "<<i<<' '<<j<<" +";ll h=finish();mutex.emplace(k,h);++derived;return h;}throw runtime_error("unsupported same-group AMO");};
map<int,vector<ll>> ticks;auto build=[&](int m){if(ticks.count(m))return;vector<vector<int>> starts(H),ends(H+1);for(int u:machines.at(m)){auto&z=g[u];for(int i=0;i<(int)z.x.size();i++){starts[z.r+i].push_back(z.x[i]);ends[z.r+i+z.p].push_back(z.x[i]);}}auto&caps=ticks[m];caps.resize(H);set<int>active;ll amo=0;for(int t=0;t<H;t++){if(!ends[t].empty()){if(amo&&active.size()-ends[t].size()>=2){out<<"pol "<<amo;for(int x:ends[t])out<<" x"<<x<<" w";amo=finish();}else amo=0;for(int x:ends[t])req(active.erase(x)==1,"inactive");}for(int x:starts[t]){if(active.size()==1)amo=edge(*active.begin(),x);else if(active.size()>=2){vector<ll> es;for(int y:active)es.push_back(edge(x,y));out<<"pol "<<amo<<' '<<active.size()-1<<" *";for(ll e:es)out<<' '<<e<<" +";out<<' '<<active.size()<<" d";amo=finish();}active.insert(x);}if(active.size()>=2)caps[t]=amo;else if(active.size()==1){out<<"pol ~x"<<*active.begin();caps[t]=finish();}}};
map<tuple<int,int,int>,ll> cap;auto capacity=[&](int m,int a,int b){auto k=make_tuple(m,a,b);if(cap.count(k)){++cap_reuse;return cap[k];}build(m);bool first=true;for(int t=a;t<b;t++){ll c=ticks[m][t];if(!c)continue;if(first){out<<"pol "<<c;first=false;}else out<<' '<<c<<" +";}req(!first,"empty capacity");return cap[k]=finish();};
auto overlap=[](int s,int p,int a,int b){return max(0,min(s+p,b)-max(s,a));};auto minimum=[&](int u,int a,int b){auto&z=g[u];int e=b-a+1;for(int i=0;i<(int)z.x.size();i++)if(z.d[i])e=min(e,overlap(z.r+i,z.p,a,b));req(e<=b-a,"empty group");return e;};
map<tuple<int,int,int,int>,ll> lower;auto lb=[&](int u,int a,int b,int e){auto k=make_tuple(u,a,b,e);if(lower.count(k))return lower[k];auto&z=g[u];bool any=false;for(int i=0;i<(int)z.x.size();i++)if(overlap(z.r+i,z.p,a,b))any=true;if(!any){req(e==0,"zero weight");return 0ll;}out<<"rup";for(int i=0;i<(int)z.x.size();i++){int w=overlap(z.r+i,z.p,a,b);if(w)out<<' '<<w<<" x"<<z.x[i];}out<<" >= "<<e;return lower[k]=finish();};
map<tuple<int,int,int>,pair<int,ll>> bounds;
for(auto[t,u,i,a,b]:trace){if(t==0){req(i>=0&&i<(int)g[u].x.size()&&g[u].d[i],"AC selector");out<<"rup 1 ~x"<<g[u].x[i]<<" >= 1";finish();g[u].d[i]=0;++ac;continue;}
if(t==3){out<<"rup >= 1";finish();break;}
int m=t==2?u:g[u].m;if(t==2){b=a;a=i;}req(a>=0&&b>a&&b<=H,"interval");int demand=0;vector<pair<int,int>> terms;for(int v:machines.at(m))if(t==2||v!=u){int e=minimum(v,a,b);demand+=e;terms.emplace_back(v,e);}if(t==2){req(demand>b-a,"not overload");ll c=capacity(m,a,b);vector<ll> ls;for(auto[v,e]:terms){ll l=lb(v,a,b,e);if(l)ls.push_back(l);}out<<"pol "<<c;for(ll l:ls)out<<' '<<l<<" +";finish();break;}
req(i>=0&&i<(int)g[u].x.size()&&g[u].d[i],"energy selector");int w=overlap(g[u].r+i,g[u].p,a,b);int limit=b-a-demand;req(w>limit,"unjustified cut");auto k=make_tuple(u,a,b);auto it=bounds.find(k);if(it==bounds.end()||w<=it->second.first){ll c=capacity(m,a,b);vector<ll> ls;for(auto[v,e]:terms){ll l=lb(v,a,b,e);if(l)ls.push_back(l);}out<<"pol "<<c;for(ll l:ls)out<<' '<<l<<" +";ll q=finish();bounds[k]={limit,q};}else ++bound_reuse;
out<<"rup 1 ~x"<<g[u].x[i]<<" >= 1";finish();g[u].d[i]=0;++energy;
}out<<"output NONE ;\nconclusion UNSAT ;\nend pseudo-Boolean proof ;\n";req(bool(out),"write proof");cerr<<"EMITTED_UNCHECKED steps="<<steps<<" derived_pairs="<<derived<<" ac="<<ac<<" energy="<<energy<<" interval_cache="<<cap.size()<<" cap_reuse="<<cap_reuse<<" bound_reuse="<<bound_reuse<<'\n';return 0;
}catch(exception&e){cerr<<"REJECTED "<<e.what()<<'\n';return 1;}}
